const PptxGenJS = require('pptxgenjs');
const pres = new PptxGenJS();

pres.layout = 'LAYOUT_WIDE'; // 13.33 x 7.5 inches

// Color palette
const TITLE_COLOR = '1B3A5C';
const SUBTITLE_COLOR = '4A6FA5';
const BODY_COLOR = '333333';
const ACCENT_GREEN = '2E7D32';
const ACCENT_ORANGE = 'E65100';
const ACCENT_GRAY = '757575';

// ============================================================
// Slide 1: Objectives / 目标
// ============================================================
const slide1 = pres.addSlide();

// Title area
slide1.addText('Objectives\n目标', {
  x: 0.8, y: 0.4, w: 11.7, h: 1.4,
  fontSize: 36, fontFace: 'Arial',
  color: TITLE_COLOR, bold: true, align: 'left',
  lineSpacingMultiple: 1.1
});

// Divider line
slide1.addShape(pres.ShapeType.rect, {
  x: 0.8, y: 1.9, w: 4.0, h: 0.06,
  fill: { color: SUBTITLE_COLOR }
});

// English objective
slide1.addText([
  { text: 'Project Morning Star\n', options: { fontSize: 22, bold: true, color: SUBTITLE_COLOR } },
  { text: 'Conduct a test demonstration to validate the synthetic approach.\n', options: { fontSize: 18, color: BODY_COLOR } },
  { text: '\nBudget: ', options: { fontSize: 16, bold: true, color: BODY_COLOR } },
  { text: 'TBD\n', options: { fontSize: 16, color: ACCENT_GRAY, italic: true } },
  { text: 'Delivery Date: ', options: { fontSize: 16, bold: true, color: BODY_COLOR } },
  { text: 'TBD', options: { fontSize: 16, color: ACCENT_GRAY, italic: true } }
], {
  x: 0.8, y: 2.3, w: 5.5, h: 4.0,
  valign: 'top', lineSpacingMultiple: 1.4
});

// Chinese objective
slide1.addText([
  { text: '合成项目晨星\n', options: { fontSize: 22, bold: true, color: SUBTITLE_COLOR, fontFace: 'Microsoft YaHei' } },
  { text: '开展测试演示，验证合成技术路线的可行性。\n', options: { fontSize: 18, color: BODY_COLOR, fontFace: 'Microsoft YaHei' } },
  { text: '\n预算：', options: { fontSize: 16, bold: true, color: BODY_COLOR, fontFace: 'Microsoft YaHei' } },
  { text: '待定\n', options: { fontSize: 16, color: ACCENT_GRAY, italic: true, fontFace: 'Microsoft YaHei' } },
  { text: '交付日期：', options: { fontSize: 16, bold: true, color: BODY_COLOR, fontFace: 'Microsoft YaHei' } },
  { text: '待定', options: { fontSize: 16, color: ACCENT_GRAY, italic: true, fontFace: 'Microsoft YaHei' } }
], {
  x: 7.0, y: 2.3, w: 5.5, h: 4.0,
  valign: 'top', lineSpacingMultiple: 1.4
});

// Vertical divider between EN/CN
slide1.addShape(pres.ShapeType.rect, {
  x: 6.5, y: 2.3, w: 0.03, h: 4.0,
  fill: { color: 'CCCCCC' }
});

// Footer
slide1.addText('Synthetic Morning Star | 合成项目晨星', {
  x: 0.8, y: 6.9, w: 11.7, h: 0.4,
  fontSize: 10, color: '999999', align: 'right'
});


// ============================================================
// Slide 2: Experimental Results / 实验结果
// ============================================================
const slide2 = pres.addSlide();

slide2.addText('Experimental Results\n实验结果', {
  x: 0.8, y: 0.4, w: 11.7, h: 1.4,
  fontSize: 36, fontFace: 'Arial',
  color: TITLE_COLOR, bold: true, align: 'left',
  lineSpacingMultiple: 1.1
});

slide2.addShape(pres.ShapeType.rect, {
  x: 0.8, y: 1.9, w: 4.0, h: 0.06,
  fill: { color: SUBTITLE_COLOR }
});

// Summary callout box
slide2.addShape(pres.ShapeType.roundRect, {
  x: 0.8, y: 2.2, w: 11.7, h: 1.0,
  fill: { color: 'FFF3E0' },
  rectRadius: 0.1,
  line: { color: ACCENT_ORANGE, width: 1.5 }
});

slide2.addText([
  { text: '⚠ Not all experiments passed — 1 of 3 is still awaiting review.\n', options: { fontSize: 16, bold: true, color: ACCENT_ORANGE } },
  { text: '并非全部成功——3次实验中仍有1次待复核。', options: { fontSize: 16, bold: true, color: ACCENT_ORANGE, fontFace: 'Microsoft YaHei' } }
], {
  x: 1.1, y: 2.25, w: 11.1, h: 0.9,
  valign: 'middle', lineSpacingMultiple: 1.3
});

// Three experiment cards
const cardY = 3.6;
const cardH = 2.8;
const cardW = 3.5;
const gap = 0.4;
const startX = 0.8;

// Card 1: Experiment 1 - Passed
slide2.addShape(pres.ShapeType.roundRect, {
  x: startX, y: cardY, w: cardW, h: cardH,
  fill: { color: 'E8F5E9' }, rectRadius: 0.1,
  line: { color: ACCENT_GREEN, width: 1.5 }
});
slide2.addText([
  { text: 'Experiment 1 / 实验 1\n', options: { fontSize: 16, bold: true, color: ACCENT_GREEN, fontFace: 'Microsoft YaHei' } },
  { text: '\n✓ PASSED\n', options: { fontSize: 28, bold: true, color: ACCENT_GREEN } },
  { text: '通过', options: { fontSize: 18, color: ACCENT_GREEN, fontFace: 'Microsoft YaHei' } }
], {
  x: startX, y: cardY, w: cardW, h: cardH,
  align: 'center', valign: 'middle', lineSpacingMultiple: 1.2
});

// Card 2: Experiment 2 - Passed
slide2.addShape(pres.ShapeType.roundRect, {
  x: startX + cardW + gap, y: cardY, w: cardW, h: cardH,
  fill: { color: 'E8F5E9' }, rectRadius: 0.1,
  line: { color: ACCENT_GREEN, width: 1.5 }
});
slide2.addText([
  { text: 'Experiment 2 / 实验 2\n', options: { fontSize: 16, bold: true, color: ACCENT_GREEN, fontFace: 'Microsoft YaHei' } },
  { text: '\n✓ PASSED\n', options: { fontSize: 28, bold: true, color: ACCENT_GREEN } },
  { text: '通过', options: { fontSize: 18, color: ACCENT_GREEN, fontFace: 'Microsoft YaHei' } }
], {
  x: startX + cardW + gap, y: cardY, w: cardW, h: cardH,
  align: 'center', valign: 'middle', lineSpacingMultiple: 1.2
});

// Card 3: Experiment 3 - Awaiting Review
slide2.addShape(pres.ShapeType.roundRect, {
  x: startX + 2 * (cardW + gap), y: cardY, w: cardW, h: cardH,
  fill: { color: 'FFF3E0' }, rectRadius: 0.1,
  line: { color: ACCENT_ORANGE, width: 1.5 }
});
slide2.addText([
  { text: 'Experiment 3 / 实验 3\n', options: { fontSize: 16, bold: true, color: ACCENT_ORANGE, fontFace: 'Microsoft YaHei' } },
  { text: '\n◷ AWAITING\nREVIEW\n', options: { fontSize: 24, bold: true, color: ACCENT_ORANGE } },
  { text: '待复核', options: { fontSize: 18, color: ACCENT_ORANGE, fontFace: 'Microsoft YaHei' } }
], {
  x: startX + 2 * (cardW + gap), y: cardY, w: cardW, h: cardH,
  align: 'center', valign: 'middle', lineSpacingMultiple: 1.2
});

// Footer
slide2.addText('Synthetic Morning Star | 合成项目晨星', {
  x: 0.8, y: 6.9, w: 11.7, h: 0.4,
  fontSize: 10, color: '999999', align: 'right'
});


// ============================================================
// Slide 3: Next Steps / 下一步
// ============================================================
const slide3 = pres.addSlide();

slide3.addText('Next Steps\n下一步', {
  x: 0.8, y: 0.4, w: 11.7, h: 1.4,
  fontSize: 36, fontFace: 'Arial',
  color: TITLE_COLOR, bold: true, align: 'left',
  lineSpacingMultiple: 1.1
});

slide3.addShape(pres.ShapeType.rect, {
  x: 0.8, y: 1.9, w: 4.0, h: 0.06,
  fill: { color: SUBTITLE_COLOR }
});

// Left column: English next steps
slide3.addText([
  { text: 'English\n', options: { fontSize: 20, bold: true, color: SUBTITLE_COLOR } },
  { text: '\n1. Complete the review of Experiment 3\n', options: { fontSize: 16, color: BODY_COLOR } },
  { text: '2. Analyze root cause if Experiment 3 fails\n', options: { fontSize: 16, color: BODY_COLOR } },
  { text: '3. Confirm project budget and delivery timeline\n', options: { fontSize: 16, color: BODY_COLOR } },
  { text: '4. Plan follow-up experiments based on results\n', options: { fontSize: 16, color: BODY_COLOR } },
  { text: '5. Prepare formal demonstration report', options: { fontSize: 16, color: BODY_COLOR } }
], {
  x: 0.8, y: 2.3, w: 5.5, h: 4.2,
  valign: 'top', lineSpacingMultiple: 1.5
});

// Vertical divider
slide3.addShape(pres.ShapeType.rect, {
  x: 6.5, y: 2.3, w: 0.03, h: 4.2,
  fill: { color: 'CCCCCC' }
});

// Right column: Chinese next steps
slide3.addText([
  { text: '中文\n', options: { fontSize: 20, bold: true, color: SUBTITLE_COLOR, fontFace: 'Microsoft YaHei' } },
  { text: '\n1. 完成实验3的复核工作\n', options: { fontSize: 16, color: BODY_COLOR, fontFace: 'Microsoft YaHei' } },
  { text: '2. 若实验3未通过，分析根本原因\n', options: { fontSize: 16, color: BODY_COLOR, fontFace: 'Microsoft YaHei' } },
  { text: '3. 确认项目预算与交付时间表\n', options: { fontSize: 16, color: BODY_COLOR, fontFace: 'Microsoft YaHei' } },
  { text: '4. 根据实验结果规划后续实验\n', options: { fontSize: 16, color: BODY_COLOR, fontFace: 'Microsoft YaHei' } },
  { text: '5. 编写正式测试演示报告', options: { fontSize: 16, color: BODY_COLOR, fontFace: 'Microsoft YaHei' } }
], {
  x: 7.0, y: 2.3, w: 5.5, h: 4.2,
  valign: 'top', lineSpacingMultiple: 1.5
});

// Footer
slide3.addText('Synthetic Morning Star | 合成项目晨星', {
  x: 0.8, y: 6.9, w: 11.7, h: 0.4,
  fontSize: 10, color: '999999', align: 'right'
});


// Write file
pres.writeFile({ fileName: '/workspace/slides.pptx' })
  .then(() => console.log('PPTX created successfully'))
  .catch(err => { console.error('Error:', err); process.exit(1); });

